import os
import json
import carb
from typing import List, Tuple

import carb.dictionary
import omni.client
from datetime import datetime, timedelta, timezone

from .registry_manager import get_registry_manager_instance
from .utils.omni_client_utils import omni_client_list_async
from .index_v2.index_sync import read_remote_zip_to_json


def get_registry_url_by_name(registry_name: str) -> str:
    """Get registry url by registry name."""
    manager = get_registry_manager_instance()
    provider = manager.get_provider(registry_name)
    if provider:
        urls = provider.get_urls()
        if urls:
            return urls.index


def get_registry_url_by_ext_dict(ext_dict: carb.dictionary.Item) -> str:
    """Get registry url using extension data dictionary."""
    return get_registry_url_by_name(ext_dict.get("registryProviderName", None))


def get_package_resource_url_by_key(key: str, ext_dict: carb.dictionary.Item) -> str:
    """Get package resource url using extension data dictionary by key in package dict (like icon_remote)."""
    registry_url = get_registry_url_by_ext_dict(ext_dict)
    if not registry_url:
        return None

    preview_image_remote = ext_dict.get("package", {}).get(key, None)
    if preview_image_remote:
        return f"{registry_url}/{preview_image_remote}"


def get_preview_image_url(ext_dict: carb.dictionary.Item) -> str:
    """Get preview image url using extension data dictionary."""
    return get_package_resource_url_by_key("preview_image_remote", ext_dict)


def get_icon_url(ext_dict: carb.dictionary.Item) -> str:
    """Get icon url using extension data dictionary."""
    return get_package_resource_url_by_key("icon_remote", ext_dict)


def get_extension_metadata_possible_urls(ext_dict: carb.dictionary.Item) -> List[str]:
    """Get possible urls for extension metadata using extension data dictionary.

    To support older format, more than one url can be returned if extension is hosted on different host than registry.

    The first one is the most likely to be correct.
    """

    registry_url = get_registry_url_by_ext_dict(ext_dict)
    if not registry_url:
        return []

    package_dict = archive_path = ext_dict.get("package", {})
    # Same as archive path, but extension is `.json`:
    archive_path = package_dict.get("archivePath", None)
    if archive_path:
        # build url relative to the registry url
        archive_path = archive_path.replace("\\", "/")
        archive_path = omni.client.combine_urls(registry_url + "/index.zip", archive_path)
        archive_path = omni.client.normalize_url(archive_path)
        archive_path = os.path.splitext(archive_path)[0] + ".json"

        paths = []
        # if archive is on the same host as registry (usually on nucleus), try archive path first. Metadata would be
        # next to it
        if omni.client.break_url(archive_path).host == omni.client.break_url(registry_url).host:
            paths.append(archive_path)

        # If archive path is on different host (like packman). Do the best guess using registry url.
        # Old format is one big folder, new format is a subfolder for each extension
        data_filename = os.path.basename(archive_path)
        ext_name = package_dict.get("name", "")
        package_id = package_dict.get("packageId", "")
        for path in (
            f"{registry_url}/archives/{ext_name}/{data_filename}",
            f"{registry_url}/archives/{ext_name}/{package_id}.json",
            f"{registry_url}/archives/{data_filename}",
            f"{registry_url}/archives/{package_id}.json",
        ):
            if path not in paths:
                paths.append(path)
        return paths

    return []


def get_extension_metadata_url(ext_dict: carb.dictionary.Item) -> str:
    """Get extension metadata url using extension data dictionary.

    Only the latest supported format is returned. To get all possible urls use `get_extension_metadata_possible_urls`.
    """
    urls = get_extension_metadata_possible_urls(ext_dict)
    if urls:
        return urls[0]


async def get_extension_metadata_async(ext_dict: carb.dictionary.Item) -> dict:
    """Get extension metadata using extension data dictionary

    Returns:
        dict: Extension metadata dictionary or None if not found.
    """

    json_data_urls = get_extension_metadata_possible_urls(ext_dict)
    if json_data_urls:
        for json_data_url in json_data_urls:
            result, _, content = await omni.client.read_file_async(json_data_url)
            if result == omni.client.Result.OK:
                try:
                    content = memoryview(content).tobytes().decode("utf-8")
                    return json.loads(content)
                except Exception as e:  # noqa
                    pass

    return None


async def get_all_registry_changes(registry_url: str, start_date: datetime, end_date: datetime) -> List[Tuple[str, str, dict, bool]]:
    """Get all registry changes within the specified date range.

    Args:
        registry_url: The base URL of the registry
        start_date: Start date (inclusive) for filtering changes. Must be timezone-aware.
        end_date: End date (inclusive) for filtering changes. Must be timezone-aware.

    Returns:
        List of tuples containing (file_url, ext_id, ext_data, add_flag), where:
            file_url: The full URL of the file
            ext_id: The extension ID
            ext_data: The extension data
            add_flag: True if the extension was added or updated, False if it was removed

    Raises:
        ValueError: If start_date or end_date is not timezone-aware

    Example:
        entries = await get_all_registry_changes(url, datetime.now().astimezone() - timedelta(hours=8), datetime.now().astimezone())
    """
    # If there is no timezone, assume local timezone:
    if start_date.tzinfo is None:
        raise ValueError("start_date must be timezone-aware")
    if end_date.tzinfo is None:
        raise ValueError("end_date must be timezone-aware")

    # Convert dates to UTC for comparison with UTC filenames
    start_date = start_date.astimezone(timezone.utc)
    end_date = end_date.astimezone(timezone.utc)

    # Determine which month folders to check
    month_folders = set()
    current = start_date.replace(day=1)  # Start of month
    while current <= end_date:
        month_folders.add(current.strftime("%Y-%m"))
        # Move to next month
        if current.month == 12:
            current = current.replace(year=current.year + 1, month=1)
        else:
            current = current.replace(month=current.month + 1)

    month_folders = sorted(list(month_folders))

    carb.log_info(f"Getting registry changes in {registry_url} from {start_date} to {end_date}...")

    def is_file_in_date_range(file_url: str) -> bool:
        """
        Check if a change file falls within the specified date range based on its timestamp in the filename.

        File timestamps are in UTC timezone.
        """
        filename = file_url.split("/")[-1]

        # Check if it's a changes file
        if not (filename.startswith("changes_") and filename.endswith(".gz")):
            return False

        # Extract timestamp part: changes_2025-06-28T00-06-54.017.gz -> 2025-06-28T00-06-54.017
        timestamp_str = filename[8:-3]  # Remove 'changes_' prefix and '.gz' suffix

        try:
            # Parse timestamp (handle milliseconds)
            timestamp_parts = timestamp_str.split(".")
            base_timestamp = timestamp_parts[0]
            file_time = datetime.strptime(base_timestamp, "%Y-%m-%dT%H-%M-%S")
            # File timestamps are in UTC
            file_time = file_time.replace(tzinfo=timezone.utc)

            # Check if file time is within the date range (both already converted to UTC)
            return start_date <= file_time <= end_date
        except Exception:
            # If we can't parse the timestamp, skip this file
            return False

    changes = []
    for month_folder in sorted(month_folders):
        url = f"{registry_url}/v2/logs/{month_folder}"
        result, remote_files = await omni_client_list_async(url)
        if result != omni.client.Result.OK:
            raise Exception(f"Failed to list remote files {url}: {result}")

        remote_files = sorted([f"{url}/{f.relative_path}" for f in remote_files])
        for file_url in remote_files:
            # file_url looks like this: omniverse://kit-extensions.ov.nvidia.com/exts/kit/debug/v2/logs/2025-06/changes_2025-06-28T00-06-54.017.gz

            # Skip files outside the date range
            if not is_file_in_date_range(file_url):
                continue

            content, result = read_remote_zip_to_json(file_url)
            if result != omni.client.Result.OK:
                raise Exception(f"Failed to read remote zip file {file_url}: {result}")
            for change in content:
                changes.append((file_url, change["ext_id"], change["ext_data"], change["add"]))

    return changes
